20	// The tests here never reach a real skopeo: PATH holds a stand-in started
21	// through the helper process (helper_process_test.go), which records its
22	// arguments, its environment and the files it was pointed at. They need no
23	// cluster, no network and no requireBench guard. TestSkopeoAgainstFakeRegistry
24	// (fakeregistry_test.go) is the one test that runs the real binary, against a
25	// registry served from the test process.
26	
27	const (
28		srcHost  = "127.0.0.1:41234"
29		destHost = "127.0.0.1:43210"
30		srcPass  = "src-pw-9f3a1c"
31		destPass = "dest-pw-77c1d2"
32	)
