65	func TestNewSkopeoCopierSkopeoMissing(t *testing.T) {
66		// An empty directory as the whole PATH: no skopeo can be found, whatever
67		// the host has installed.
68		t.Setenv("PATH", t.TempDir())
69	
70		c, err := NewSkopeoCopier()
71		if err == nil {
72			t.Fatal("NewSkopeoCopier succeeded without skopeo on PATH")
73		}
74		if c != nil {
75			t.Errorf("copier = %v, want nil on error", c)
76		}
77		var be *BenchError
78		if !errors.As(err, &be) {
79			t.Fatalf("error %T is not a *BenchError: %v", err, err)
80		}
81		if be.Kind != SkopeoMissing {
82			t.Errorf("Kind = %d, want SkopeoMissing (%d)", be.Kind, SkopeoMissing)
83		}
84		if !strings.Contains(err.Error(), "skopeo") {
85			t.Errorf("message %q does not name skopeo", err.Error())
86		}
87	}
