89	// ---- the arguments of copy -----------------------------------------------------
90	
91	// credCombo is one choice of credentials for a copy.
92	type credCombo struct {
93		name     string
94		src, dst *Credentials
95	}
96	
97	// Every no-credentials, TLS and digest flag follows from the two references and
98	// the options; nothing else decides it.
99	func TestSkopeoCopyArguments(t *testing.T) {
100		srcs := map[string]ImageRef{
101			"oci":    {Transport: "oci", Location: "/var/tmp/layout:img-01"},
102			"dir":    {Transport: "dir", Location: "/var/tmp/in"},
103			"docker": {Transport: "docker", Location: srcHost + "/mirror/cached:1.0"},
104		}
105		dsts := map[string]ImageRef{
106			"oci":    {Transport: "oci", Location: "/var/tmp/out-layout:img-01"},
107			"dir":    {Transport: "dir", Location: "/var/tmp/out"},
108			"docker": {Transport: "docker", Location: destHost + "/docker-hosted/api:1.0.0"},
109		}
110		srcCreds := &Credentials{User: "bench-pull", Password: srcPass}
111		destCreds := &Credentials{User: "admin", Password: destPass}
112	
113		for _, sn := range []string{"oci", "dir", "docker"} {
114			for _, dn := range []string{"oci", "dir", "docker"} {
115				// Credentials only make sense on a registry side.
116				combos := []credCombo{{"anonymous", nil, nil}}
117				if sn == "docker" {
118					combos = append(combos, credCombo{"source credentials", srcCreds, nil})
119				}
120				if dn == "docker" {
121					combos = append(combos, credCombo{"destination credentials", nil, destCreds})
122				}
123				if sn == "docker" && dn == "docker" {
124					combos = append(combos, credCombo{"both credentials", srcCreds, destCreds})
125				}
126				for _, combo := range combos {
127					for _, preserve := range []bool{false, true} {
128						name := fmt.Sprintf("%s to %s, %s, preserve=%v", sn, dn, combo.name, preserve)
129						t.Run(name, func(t *testing.T) {
130							c, tool := newHelperSkopeo(t, nil)
131							src, dst := srcs[sn], dsts[dn]
132							o := CopyOptions{SrcCreds: combo.src, DestCreds: combo.dst, PreserveDigests: preserve}
133	
134							if err := c.Copy(context.Background(), src, dst, o); err != nil {
135								t.Fatalf("Copy: %v", err)
136							}
137	
138							rec := tool.last(t)
139							checkCopyArgs(t, rec, src, dst, o)
140							checkNoSecretLeak(t, rec, srcPass, destPass)
141							checkAuthfiles(t, rec, src, dst, o)
142						})
143					}
144				}
145			}
146		}
147	}
