282	// Whatever skopeo is given, TLS verification is switched off for a docker
283	// reference, so a host that is not the loopback is refused before any process
284	// starts.
285	func TestSkopeoRefusesANonLoopbackDockerReference(t *testing.T) {
286		locations := []string{
287			"192.168.1.31:30481/docker-hosted/api:1.0.0", // the bench node itself, by its LAN address
288			"example.com/library/busybox:1",
289			"example.com:5000/library/busybox:1",
290			"localhost.evil.com/x:1",
291			"localhost.evil.com:5000/x:1",
292			"127.0.0.1.evil.com/x:1",
293			"127.0.0.1.evil.com:5000/x:1",
294			"127.0.0.1@evil.com/x:1",
295			"127.0.0.1:5000@evil.com/x:1",
296			"evil.com/127.0.0.1:5000/x:1",
297			"0.0.0.0:5000/x:1",
298			"10.0.0.1:5000/x:1",
299			"[::2]:5000/x:1",
300			"nexus.bench.svc.cluster.local:5000/x:1",
301			"/x:1", // no host
302			"",
303		}
304		creds := &Credentials{User: "admin", Password: destPass}
305		local := ImageRef{Transport: "dir", Location: "/var/tmp/out"}
306	
307		for _, loc := range locations {
308			bad := ImageRef{Transport: "docker", Location: loc}
309			for _, op := range []string{"source", "destination", "inspect"} {
310				t.Run(op+" "+loc, func(t *testing.T) {
311					c, tool := newHelperSkopeo(t, nil)
312					var err error
313					switch op {
314					case "source":
315						err = c.Copy(context.Background(), bad, local, CopyOptions{SrcCreds: creds})
316					case "destination":
317						err = c.Copy(context.Background(), local, bad, CopyOptions{DestCreds: creds})
318					case "inspect":
319						_, err = c.ManifestDigest(context.Background(), bad, creds)
320					}
321					if err == nil {
322						t.Fatalf("%s %q was accepted", op, loc)
323					}
324					var be *BenchError
325					if !errors.As(err, &be) {
326						t.Errorf("error %T is not a *BenchError: %v", err, err)
327					}
328					if strings.Contains(err.Error(), destPass) {
329						t.Errorf("the message carries a password: %q", err.Error())
330					}
331					tool.neverRan(t)
332					entries, _ := os.ReadDir(tool.scratch)
333					if len(entries) != 0 {
334						t.Errorf("the refusal left %d file(s) in the temporary folder", len(entries))
335					}
336				})
337			}
338		}
339	}
