341	func TestSkopeoAcceptsLoopbackDockerReferences(t *testing.T) {
342		locations := []string{
343			"127.0.0.1:41234/docker-hosted/api:1.0.0",
344			"127.0.0.1/x:1",
345			"127.0.0.1:5000/x@sha256:" + strings.Repeat("a", 64),
346			"localhost:5000/x:1",
347			"localhost/x:1",
348			"[::1]:5000/x:1",
349			"[::1]/x:1",
350		}
351		local := ImageRef{Transport: "dir", Location: "/var/tmp/out"}
352		for _, loc := range locations {
353			t.Run(loc, func(t *testing.T) {
354				c, tool := newHelperSkopeo(t, nil)
355				good := ImageRef{Transport: "docker", Location: loc}
356	
357				if err := c.Copy(context.Background(), good, local, CopyOptions{}); err != nil {
358					t.Fatalf("Copy from %q: %v", loc, err)
359				}
360				if err := c.Copy(context.Background(), local, good, CopyOptions{}); err != nil {
361					t.Fatalf("Copy to %q: %v", loc, err)
362				}
363				if got := len(tool.records(t)); got != 2 {
364					t.Errorf("skopeo ran %d time(s), want 2", got)
365				}
366			})
367		}
368	}
