382	// ---- the environment -------------------------------------------------------------
383	
384	// removedFromSkopeoEnvironment are the variables that would let the host's own
385	// settings (proxies, an authentication file, containers configuration) change
386	// where skopeo goes or who it is. CONTAINERS_REGISTRIES_CONF is replaced, not
387	// dropped.
388	var removedFromSkopeoEnvironment = []string{
389		"HTTP_PROXY", "http_proxy", "HTTPS_PROXY", "https_proxy", "ALL_PROXY", "all_proxy", "NO_PROXY", "no_proxy",
390		"REGISTRY_AUTH_FILE",
391		"CONTAINERS_CONF", "CONTAINERS_STORAGE_CONF", "CONTAINERS_POLICY", "CONTAINERS_CERT_DIR", "CONTAINERS_ANYTHING_ELSE",
392	}
393	
394	func TestSkopeoEnvironment(t *testing.T) {
395		for _, name := range removedFromSkopeoEnvironment {
396			t.Setenv(name, "http://elsewhere.invalid:3128")
397		}
398		t.Setenv("CONTAINERS_REGISTRIES_CONF", "/etc/containers/registries.conf")
399		t.Setenv("DEVDESK_KEEP", "1")
400		t.Setenv("HOME", "/home/keep")
401	
402		env := skopeoEnvironment("/run/empty/registries.conf")
403	
404		counts := map[string]int{}
405		for _, kv := range env {
406			name, _, _ := strings.Cut(kv, "=")
407			counts[name]++
408			if slices.Contains(removedFromSkopeoEnvironment, name) {
409				t.Errorf("skopeoEnvironment keeps %s", kv)
410			}
411		}
412		if !slices.Contains(env, "CONTAINERS_REGISTRIES_CONF=/run/empty/registries.conf") || counts["CONTAINERS_REGISTRIES_CONF"] != 1 {
413			t.Errorf("CONTAINERS_REGISTRIES_CONF is not pinned to the empty file exactly once (seen %d, env %q)", counts["CONTAINERS_REGISTRIES_CONF"], env)
414		}
415		for _, keep := range []string{"DEVDESK_KEEP=1", "HOME=/home/keep"} {
416			if !slices.Contains(env, keep) {
417				t.Errorf("skopeoEnvironment dropped %s, which is not about proxies or containers settings", keep)
418			}
419		}
420		if _, ok := envOf(env, "PATH"); !ok {
421			t.Error("skopeoEnvironment dropped PATH")
422		}
423	}
