425	// The same rule seen from the process: what skopeo is started with.
426	func TestSkopeoRunsWithACleanEnvironment(t *testing.T) {
427		c, tool := newHelperSkopeo(t, nil)
428		for _, name := range removedFromSkopeoEnvironment {
429			t.Setenv(name, "http://elsewhere.invalid:3128")
430		}
431		t.Setenv("CONTAINERS_REGISTRIES_CONF", "/etc/containers/registries.conf")
432		t.Setenv("DEVDESK_KEEP", "1")
433	
434		err := c.Copy(context.Background(),
435			ImageRef{Transport: "docker", Location: srcHost + "/x:1"},
436			ImageRef{Transport: "dir", Location: "/var/tmp/out"},
437			CopyOptions{})
438		if err != nil {
439			t.Fatalf("Copy: %v", err)
440		}
441	
442		rec := tool.last(t)
443		for _, kv := range rec.Env {
444			name, _, _ := strings.Cut(kv, "=")
445			if slices.Contains(removedFromSkopeoEnvironment, name) {
446				t.Errorf("skopeo was started with %s", kv)
447			}
448		}
449		if v, _ := envOf(rec.Env, "DEVDESK_KEEP"); v != "1" {
450			t.Error("skopeo was started without a variable that is not about proxies or containers settings")
451		}
452		if rec.RegistriesConf == "" || rec.RegistriesConf == "/etc/containers/registries.conf" {
453			t.Fatalf("CONTAINERS_REGISTRIES_CONF = %q, want a file of the bench", rec.RegistriesConf)
454		}
455		if !rec.RegistriesConfExists || rec.RegistriesConfSize != 0 {
456			t.Errorf("registries.conf exists = %v, size = %d, want an existing empty file while skopeo runs", rec.RegistriesConfExists, rec.RegistriesConfSize)
457		}
458		if !strings.HasPrefix(rec.RegistriesConf, tool.scratch) {
459			t.Errorf("registries.conf %s is outside the temporary folder %s", rec.RegistriesConf, tool.scratch)
460		}
461	}
