465	func TestSkopeoPolicyAcceptsAnythingFromATemporaryFile(t *testing.T) {
466		c, tool := newHelperSkopeo(t, nil)
467	
468		err := c.Copy(context.Background(),
469			ImageRef{Transport: "oci", Location: "/var/tmp/layout:img-01"},
470			ImageRef{Transport: "docker", Location: destHost + "/x:1"},
471			CopyOptions{})
472		if err != nil {
473			t.Fatalf("Copy: %v", err)
474		}
475	
476		rec := tool.last(t)
477		if rec.PolicyPath == "" {
478			t.Fatalf("no --policy in %q", rec.Args)
479		}
480		if !strings.HasPrefix(rec.PolicyPath, tool.scratch) {
481			t.Errorf("the policy %s is outside the temporary folder %s", rec.PolicyPath, tool.scratch)
482		}
483		var policy struct {
484			Default []struct {
485				Type string `json:"type"`
486			} `json:"default"`
487			Transports map[string]any `json:"transports"`
488		}
489		if err := json.Unmarshal([]byte(rec.Policy), &policy); err != nil {
490			t.Fatalf("the policy is not JSON: %v\n%s", err, rec.Policy)
491		}
492		if len(policy.Default) != 1 || policy.Default[0].Type != "insecureAcceptAnything" {
493			t.Errorf("policy default = %+v, want exactly insecureAcceptAnything", policy.Default)
494		}
495		if len(policy.Transports) != 0 {
496			t.Errorf("the policy has per-transport rules %v, want the default alone", policy.Transports)
497		}
498	}
