513	func TestSkopeoLeavesNothingBehind(t *testing.T) {
514		creds := &Credentials{User: "admin", Password: destPass}
515		src := ImageRef{Transport: "oci", Location: "/var/tmp/layout:img-01"}
516		dst := ImageRef{Transport: "docker", Location: destHost + "/x:1"}
517	
518		t.Run("success", func(t *testing.T) {
519			c, tool := newHelperSkopeo(t, nil)
520			if err := c.Copy(context.Background(), src, dst, CopyOptions{DestCreds: creds}); err != nil {
521				t.Fatalf("Copy: %v", err)
522			}
523			// The file existed, with the credentials, while skopeo ran...
524			if rec := tool.last(t); !authfilesHold(rec.Authfiles, destHost, creds) {
525				t.Fatalf("the authentication file did not hold the credentials while skopeo ran: %+v", rec.Authfiles)
526			}
527			// ...and is gone now.
528			scratchIsEmpty(t, tool)
529		})
530	
531		t.Run("skopeo fails", func(t *testing.T) {
532			c, tool := newHelperSkopeo(t, map[string]string{helperExitEnv: "1", helperStderrEnv: "FATA[0000] boom\n"})
533			if err := c.Copy(context.Background(), src, dst, CopyOptions{DestCreds: creds}); err == nil {
534				t.Fatal("Copy succeeded although skopeo exited 1")
535			}
536			if rec := tool.last(t); len(rec.Authfiles) == 0 || rec.Authfiles[0].Content == "" {
537				t.Fatalf("the authentication file did not exist while skopeo ran: %+v", rec.Authfiles)
538			}
539			scratchIsEmpty(t, tool)
540		})
541	
542		t.Run("inspect fails", func(t *testing.T) {
543			c, tool := newHelperSkopeo(t, map[string]string{helperExitEnv: "1", helperStderrEnv: "FATA[0000] boom\n"})
544			if _, err := c.ManifestDigest(context.Background(), dst, creds); err == nil {
545				t.Fatal("ManifestDigest succeeded although skopeo exited 1")
546			}
547			scratchIsEmpty(t, tool)
548		})
