550		t.Run("context cancelled while skopeo runs", func(t *testing.T) {
551			c, tool := newHelperSkopeo(t, map[string]string{helperHangEnv: "1"})
552			ctx, cancel := context.WithCancel(context.Background())
553			go func() {
554				tool.waitRan(5 * time.Second)
555				cancel()
556			}()
557			done := make(chan error, 1)
558			go func() { done <- c.Copy(ctx, src, dst, CopyOptions{DestCreds: creds}) }()
559			select {
560			case err := <-done:
