793	func TestSkopeoCredentialsAreRedacted(t *testing.T) {
794		const password = "REDACTED"
795		c := Credentials{User: "admin", Password: password}
796		opts := CopyOptions{SrcCreds: &c, DestCreds: &c, PreserveDigests: true}
797	
798		direct := map[string]string{
