801			"%+v":         fmt.Sprintf("%+v", c),
802			"%#v":         fmt.Sprintf("%#v", c),
803			"%s":          fmt.Sprintf("%s", c), //nolint:gosimple // the verb is the point
804			"%q":          fmt.Sprintf("%q", c),
805			"pointer %v":  fmt.Sprintf("%v", &c),
806			"pointer %+v": fmt.Sprintf("%+v", &c),
807			"pointer %#v": fmt.Sprintf("%#v", &c),
808		}
809		for verb, got := range direct {
