814				t.Errorf("%s = %q does not say it is redacted", verb, got)
815			}
816		}
817	
818		nested := map[string]string{
819			"options %v":   fmt.Sprintf("%v", opts),
820			"options %+v":  fmt.Sprintf("%+v", opts),
821			"options %#v":  fmt.Sprintf("%#v", opts),
822			"slice %v":     fmt.Sprintf("%v", []Credentials{c}),
823			"slice %+v":    fmt.Sprintf("%+v", []Credentials{c}),
824			"map %v":       fmt.Sprintf("%v", map[string]Credentials{"a": c}),
825			"struct %+v":   fmt.Sprintf("%+v", struct{ C Credentials }{c}),
826			"error %v":     fmt.Sprintf("%v", fmt.Errorf("copy with %v failed", c)),
827			"error %+v":    fmt.Sprintf("%+v", fmt.Errorf("copy with %+v failed", &c)),
828			"pointer opts": fmt.Sprintf("%+v", &opts),
829		}
830		for verb, got := range nested {
831			if strings.Contains(got, password) {
832				t.Errorf("%s prints the password: %s", verb, got)
833			}
834		}
835	
836		if _, ok := any(c).(slog.LogValuer); !ok {
837			t.Error("Credentials does not implement slog.LogValuer")
838		}
839		for name, newHandler := range map[string]func(*bytes.Buffer) slog.Handler{
840			"text": func(b *bytes.Buffer) slog.Handler { return slog.NewTextHandler(b, nil) },
841			"json": func(b *bytes.Buffer) slog.Handler { return slog.NewJSONHandler(b, nil) },
842		} {
843			var buf bytes.Buffer
844			slog.New(newHandler(&buf)).Info("copy", "creds", c, "pointer", &c)
845			if strings.Contains(buf.String(), password) {
846				t.Errorf("the %s log handler records the password: %s", name, buf.String())
847			}
848		}
