47	// fakeKubectlScript is a stand-in kubectl: it writes its arguments, one per
48	// line, and its standard input to the files named by the environment, answers
49	// on both streams and exits with the requested code.
50	const fakeKubectlScript = `#!/bin/sh
51	printf '%s\n' "$@" > "$KUBECTL_FAKE_ARGS"
52	cat > "$KUBECTL_FAKE_STDIN"
53	echo "stdout-line"
54	echo "stderr-line" >&2
55	exit "${KUBECTL_FAKE_EXIT:-0}"
56	`
