62	// installFakeKubectl puts the script first on PATH and points it at two files
63	// of the test's temporary directory. The script needs a POSIX shell.
64	func installFakeKubectl(t *testing.T) fakeKubectlBinary {
65		t.Helper()
66		if runtime.GOOS == "windows" {
67			t.Skip("the stand-in kubectl is a POSIX shell script")
68		}
69		bin := t.TempDir()
70		if err := os.WriteFile(filepath.Join(bin, "kubectl"), []byte(fakeKubectlScript), 0o755); err != nil { //nolint:gosec // an executable script is the point
71			t.Fatalf("writing the stand-in kubectl: %v", err)
72		}
73		t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
74	
75		out := t.TempDir()
76		b := fakeKubectlBinary{argsFile: filepath.Join(out, "args"), stdinFile: filepath.Join(out, "stdin")}
77		t.Setenv("KUBECTL_FAKE_ARGS", b.argsFile)
78		t.Setenv("KUBECTL_FAKE_STDIN", b.stdinFile)
79		t.Setenv("KUBECTL_FAKE_EXIT", "0")
80		return b
81	}
