369	// requireSkopeoKind fails unless err is a BenchError of the kind, and says
370	// nothing of what skopeo printed.
371	func requireSkopeoKind(t *testing.T, err error, kind ErrKind) {
372		t.Helper()
373		if err == nil {
374			t.Fatalf("no error, want a BenchError of kind %d", kind)
375		}
376		var be *BenchError
377		if !errors.As(err, &be) {
378			t.Fatalf("error %T is not a *BenchError: %v", err, err)
379		}
380		if be.Kind != kind {
381			t.Errorf("Kind = %d, want %d; message: %v", be.Kind, kind, err)
382		}
383		for _, leak := range []string{"FATA", "s3cret", "dial tcp", "level=", "Trying to pull"} {
384			if strings.Contains(err.Error(), leak) {
385				t.Errorf("the message carries %q of the output of skopeo: %q", leak, err.Error())
386			}
387		}
388	}
