// lookKubectl finds kubectl on PATH, or returns a KubectlMissing BenchError.
func lookKubectl() (string, error) {
	path, err := exec.LookPath("kubectl")
	if err != nil {
		return "", &BenchError{
			Kind:  KubectlMissing,
			Cause: "kubectl was not found on PATH",
