		switch upper {
		case "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "REGISTRY_AUTH_FILE":
			continue
		}
		if strings.HasPrefix(upper, "CONTAINERS_") {
			continue
		}
		env = append(env, kv)
	}
	return append(env, "CONTAINERS_REGISTRIES_CONF="+registriesConf)
}

